import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"38、【睽】 兑下离上","description":"周易口诀义 - 38、【睽】 兑下离上","frontmatter":{"title":"38、【睽】 兑下离上","description":"周易口诀义 - 38、【睽】 兑下离上"},"headers":[],"relativePath":"zh/classics/koujueyi/040.md","filePath":"zh/classics/koujueyi/040.md"}'),r={name:"zh/classics/koujueyi/040.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_38、【睽】-兑下离上" tabindex="-1">38、【睽】 兑下离上 <a class="header-anchor" href="#_38、【睽】-兑下离上" aria-label="Permalink to “38、【睽】 兑下离上”">​</a></h1><p>彖曰：睽，火动而上，泽动而下，二女同居，其志不同行。说而丽乎明，柔进而上行，得中而应乎刚，是以「小事吉」。天地「睽」而其事同也，男女「睽」而其志通也，万物「睽」而其事类也，「睽」之时用大矣哉！</p><p>象曰：上火下泽，「睽」。君子以同而异。</p><p>初九：悔亡。丧马勿逐，自复。见恶人，无咎。</p><p>象曰：「见恶人」，以避咎也。</p><p>九二：遇主于巷，无咎。</p><p>象曰：「遇主于巷」，未失道也。</p><p>六三：见舆曳，其牛掣，其人天且劓，无初有终。</p><p>象曰：「见舆曳」，位不当也。「无初有终」，遇刚也。</p><p>九四：睽孤，遇元夫，交孚，厉，无咎。</p><p>象曰：「交孚无咎」，志行也。</p><p>六五：悔亡。厥宗噬肤，往何咎。</p><p>象曰：「厥宗噬肤」，往有庆也。</p><p>上九：睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。</p><p>象曰：「遇雨」之「吉」，群疑亡也。</p><p>无（四库全书标明，摘录时缺豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦）</p>',16)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
